pair<int,int> sameRemainder(vector<int>& a, int n) {
    vector<int> seen(n, -1);              // remainder -> index, holes are 0..n-1
    for (int i = 0; i < (int)a.size(); i++) {
        int r = ((a[i] % n) + n) % n;
        if (seen[r] != -1) return {seen[r], i};   // guaranteed when size > n
        seen[r] = i;
    }
    return {-1, -1};
}

