def same_remainder(a, n):
    seen = [-1] * n                        # remainder -> index, holes are 0..n-1
    for i, x in enumerate(a):
        r = x % n
        if seen[r] != -1:
            return (seen[r], i)            # guaranteed when len(a) > n
        seen[r] = i
    return (-1, -1)

