int[] sameRemainder(int[] a, int n) {
    int[] seen = new int[n];
    Arrays.fill(seen, -1);                 // remainder -> index, holes are 0..n-1
    for (int i = 0; i < a.length; i++) {
        int r = ((a[i] % n) + n) % n;
        if (seen[r] != -1) return new int[]{seen[r], i};   // guaranteed when length > n
        seen[r] = i;
    }
