  const seen = new Array(n).fill(-1);      // remainder -> index, holes are 0..n-1
  for (let i = 0; i < a.length; i++) {
    const r = ((a[i] % n) + n) % n;
    if (seen[r] !== -1) return [seen[r], i];   // guaranteed when length > n
    seen[r] = i;
  }
  return [-1, -1];
